import type { Metadata } from "next";
import { QuotationScreen } from "./QuotationScreen";

export const metadata: Metadata = {
  title: "自動車保険 見積作成 ／ 代理店業務システム",
  description:
    "代理店の担当者が、お客さまと画面を見ながら自動車保険の見積を組み立て、3案を比べ、勧める案とその理由をお伝えするための画面です。",
};

export default function QuotationPage() {
  return <QuotationScreen />;
}

/**
 * 自動車保険 見積作成 — マスタと初期データ。
 *
 * 保険会社名・代理店名・人名・車種名・住所はすべて架空です。
 * 料率および割引率も、この画面のためだけに作った架空の設定です。
 */

/** 画面の「今日」。SSR とクライアントで表示がぶれないよう固定値で持つ。 */
export const TODAY = "2026-08-25";

/* ------------------------------------------------------------------ *
 * 契約者・車両
 * ------------------------------------------------------------------ */

export type LicenseColor = "gold" | "blue" | "green";
export type Usage = "leisure" | "commute" | "business";
export type MileageBand =
  | "u3000"
  | "u5000"
  | "u7000"
  | "u10000"
  | "u15000"
  | "unlimited";

export interface Policyholder {
  /** 氏名（架空） */
  name: string;
  /** 生年月日 yyyy-mm-dd */
  birthDate: string;
  license: LicenseColor;
  /** ノンフリート等級 1〜20 */
  grade: number;
  /** 前年の事故の有無 */
  prevAccident: boolean;
}

export interface Vehicle {
  /** 型式（架空の符号） */
  modelCode: string;
  firstRegYear: number;
  firstRegMonth: number;
  usage: Usage;
  mileage: MileageBand;
  /** 衝突被害軽減ブレーキ（ASV） */
  hasAsv: boolean;
  /** 盗難防止装置 */
  hasAntiTheft: boolean;
}

export const LICENSE_OPTIONS: { value: LicenseColor; label: string }[] = [
  { value: "gold", label: "ゴールド" },
  { value: "blue", label: "ブルー" },
  { value: "green", label: "グリーン" },
];

export const USAGE_OPTIONS: { value: Usage; label: string; factor: number }[] = [
  { value: "leisure", label: "日常・レジャー", factor: 0.94 },
  { value: "commute", label: "通勤・通学", factor: 1.0 },
  { value: "business", label: "業務", factor: 1.08 },
];

export const MILEAGE_OPTIONS: {
  value: MileageBand;
  label: string;
  factor: number;
}[] = [
  { value: "u3000", label: "3,000km以下", factor: 0.88 },
  { value: "u5000", label: "5,000km以下", factor: 0.93 },
  { value: "u7000", label: "7,000km以下", factor: 0.97 },
  { value: "u10000", label: "10,000km以下", factor: 1.0 },
  { value: "u15000", label: "15,000km以下", factor: 1.04 },
  { value: "unlimited", label: "無制限", factor: 1.08 },
];

/* ------------------------------------------------------------------ *
 * 型式マスタ（架空）
 * ------------------------------------------------------------------ */

export interface VehicleModel {
  code: string;
  /** 車種名ではなく、車体の区分だけを持つ */
  body: string;
  /** 料率クラス 1〜9 */
  bodilyClass: number;
  propertyClass: number;
  injuryClass: number;
  vehicleClass: number;
  /** 車両保険金額の目安（円） */
  vehicleValue: number;
}

export const VEHICLE_MODELS: VehicleModel[] = [
  {
    code: "KRZ-1520",
    body: "小型乗用車（5ドア）",
    bodilyClass: 4,
    propertyClass: 4,
    injuryClass: 4,
    vehicleClass: 5,
    vehicleValue: 1_850_000,
  },
  {
    code: "MSD-3308",
    body: "普通乗用車（セダン）",
    bodilyClass: 4,
    propertyClass: 5,
    injuryClass: 4,
    vehicleClass: 5,
    vehicleValue: 2_640_000,
  },
  {
    code: "TGB-7741",
    body: "軽自動車（ハイトワゴン）",
    bodilyClass: 3,
    propertyClass: 3,
    injuryClass: 3,
    vehicleClass: 4,
    vehicleValue: 1_320_000,
  },
  {
    code: "AOV-2216",
    body: "普通乗用車（SUV）",
    bodilyClass: 5,
    propertyClass: 6,
    injuryClass: 4,
    vehicleClass: 7,
    vehicleValue: 3_480_000,
  },
  {
    code: "NHW-6034",
    body: "普通乗用車（3列シート）",
    bodilyClass: 4,
    propertyClass: 5,
    injuryClass: 4,
    vehicleClass: 6,
    vehicleValue: 3_050_000,
  },
];

export function findModel(code: string): VehicleModel {
  return VEHICLE_MODELS.find((m) => m.code === code) ?? VEHICLE_MODELS[0];
}

/* ------------------------------------------------------------------ *
 * 補償の選択肢
 * ------------------------------------------------------------------ */

export type PropertyLimit = "unlimited" | "m3000";
export type InjuryLimit = "m10000" | "m5000" | "m3000in";
export type VehicleCover = "general" | "limited" | "none";
export type Deductible = "d0_10" | "d5_10" | "d10_10";

/** 対人賠償は3案とも無制限で組む（この画面の運用） */
export const BODILY_LABEL = "無制限";
export const BODILY_BASE = 22_600;

export const PROPERTY_OPTIONS: {
  value: PropertyLimit;
  label: string;
  base: number;
}[] = [
  { value: "unlimited", label: "無制限", base: 18_400 },
  { value: "m3000", label: "3,000万円", base: 15_900 },
];

export const INJURY_OPTIONS: {
  value: InjuryLimit;
  label: string;
  base: number;
}[] = [
  { value: "m10000", label: "1億円", base: 21_300 },
  { value: "m5000", label: "5,000万円", base: 15_800 },
  { value: "m3000in", label: "3,000万円（搭乗中のみ）", base: 9_400 },
];

export const VEHICLE_COVER_OPTIONS: {
  value: VehicleCover;
  label: string;
  rate: number;
  note: string;
}[] = [
  {
    value: "general",
    label: "一般型",
