  },
  {
    value: "limited",
    label: "車対車＋A",
    rate: 0.012,
    note: "相手のいる事故・盗難・災害を補償",
  },
  { value: "none", label: "付けない", rate: 0, note: "修理費は全額自己負担" },
];

/** 免責金額は1回目と2回目で額が違う */
export const DEDUCTIBLE_OPTIONS: {
  value: Deductible;
  label: string;
  first: number;
  second: number;
  discount: number;
}[] = [
  {
    value: "d0_10",
    label: "1回目 0円 ／ 2回目 10万円",
    first: 0,
    second: 100_000,
    discount: 0,
  },
  {
    value: "d5_10",
    label: "1回目 5万円 ／ 2回目 10万円",
    first: 50_000,
    second: 100_000,
    discount: 0.08,
  },
  {
    value: "d10_10",
    label: "1回目 10万円 ／ 2回目 10万円",
    first: 100_000,
    second: 100_000,
    discount: 0.14,
  },
];

/* ------------------------------------------------------------------ *
 * 特約マスタ（10件）
 * ------------------------------------------------------------------ */

export type RiderRequirement = "newCar" | "vehicleCover" | null;

export interface Rider {
  id: string;
  name: string;
