    description: "地震などで車が全損したとき50万円",
    price: 1_700,
    requires: "vehicleCover",
  },
];

export function findRider(id: string): Rider | undefined {
  return RIDERS.find((r) => r.id === id);
}

/* ------------------------------------------------------------------ *
 * 3つの案
 * ------------------------------------------------------------------ */

export type PlanId = "rich" | "standard" | "value";

export interface PlanCoverage {
  property: PropertyLimit;
  injury: InjuryLimit;
  vehicle: VehicleCover;
  deductible: Deductible;
  riders: string[];
}

export const PLAN_META: {
  id: PlanId;
  name: string;
  tagline: string;
}[] = [
  { id: "rich", name: "手厚い案", tagline: "自己負担をできるだけ小さく" },
  { id: "standard", name: "標準案", tagline: "補償と保険料の釣り合いをとる" },
  { id: "value", name: "費用を抑えた案", tagline: "年間の支払いを軽くする" },
];

export function defaultPlans(): Record<PlanId, PlanCoverage> {
  return {
    rich: {
      property: "unlimited",
      injury: "m10000",
      vehicle: "general",
      deductible: "d0_10",
      riders: [
        "legal",
