"use client";

/**
 * 3案の比較 → 担当者のお勧め → お客さまの選択と内訳 → 見積の確定。
 * 画面の右半分にあたる「お客さまに見せる面」をまとめて持つ。
 */

import * as React from "react";
import {
  IconAlertTriangle,
  IconCheck,
  IconInfoCircle,
  IconRefresh,
  IconStar,
} from "@tabler/icons-react";
import {
  Alert,
  AlertDescription,
  AlertTitle,
  AmountBreakdown,
  Badge,
  Button,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  Cluster,
  Delta,
  Dialog,
  DialogBody,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  ExpiryBadge,
  MetadataList,
  RadioCard,
  RadioCardGroup,
  Select,
  Separator,
  Statistic,
  Switch,
  Table,
  TableBody,
  TableCaption,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
  Textarea,
  Tooltip,
  TooltipContent,
  TooltipTrigger,
  formatCurrency,
  formatNumber,
  type AmountLine,
} from "@gunjo/ui";
import {
  BODILY_LABEL,
  PLAN_META,
  TODAY,
  findRider,
  type PlanCoverage,
  type PlanId,
  type Policyholder,
  type Vehicle,
} from "./data";
import {
  deductibleOption,
  formatJpDate,
  injuryOption,
  propertyOption,
  vehicleCoverOption,
  type PremiumResult,
} from "./pricing";
import { planName } from "./recommendation";

const PLAN_IDS: PlanId[] = ["rich", "standard", "value"];

export interface ConfirmedQuote {
  no: string;
  planId: PlanId;
  annual: number;
  monthly: number;
  issuedAt: string;
  expiresAt: string;
}

export interface PlanSectionsProps {
  policyholder: Policyholder;
  vehicle: Vehicle;
  plans: Record<PlanId, PlanCoverage>;
  results: Record<PlanId, PremiumResult>;
  recommended: PlanId | "none";
  onRecommendedChange: (value: PlanId | "none") => void;
  /** 画面に出ている理由の文（担当者が書き換えたものがあればそれ） */
  reason: string;
  /** いまの条件から作った文案 */
  generatedReason: string;
  reasonEdited: boolean;
  onReasonChange: (value: string) => void;
  onRegenerateReason: () => void;
  selected: PlanId;
  onSelectedChange: (value: PlanId) => void;
  confirmed: ConfirmedQuote | null;
  onConfirm: () => void;
  canConfirm: boolean;
  cannotConfirmReason: string;
}

/* ------------------------------------------------------------------ *
 * 比較表の行
 * ------------------------------------------------------------------ */

interface CompareRow {
  key: string;
  label: string;
  /** 違いの判定に使う素の値 */
  raw: Record<PlanId, string>;
  /** 表示 */
  render: Record<PlanId, React.ReactNode>;
  /** 保険料の行（太字にする） */
  emphasis?: boolean;
}

function riderNames(ids: string[]): string {
  if (ids.length === 0) return "なし";
  return ids.map((id) => findRider(id)?.name ?? id).join("、");
}

function buildCompareRows(
  plans: Record<PlanId, PlanCoverage>,
  results: Record<PlanId, PremiumResult>,
): CompareRow[] {
  const byPlan = <T,>(fn: (id: PlanId) => T): Record<PlanId, T> => ({
    rich: fn("rich"),
    standard: fn("standard"),
    value: fn("value"),
  });

  const money = (n: number) => formatCurrency(n);

  const rows: CompareRow[] = [
    {
      key: "bodily",
      label: "対人賠償",
      raw: byPlan(() => BODILY_LABEL),
      render: byPlan(() => BODILY_LABEL),
    },
    {
      key: "property",
      label: "対物賠償",
      raw: byPlan((id) => propertyOption(plans[id].property).label),
      render: byPlan((id) => propertyOption(plans[id].property).label),
    },
    {
      key: "injury",
      label: "人身傷害",
      raw: byPlan((id) => injuryOption(plans[id].injury).label),
      render: byPlan((id) => injuryOption(plans[id].injury).label),
    },
    {
      key: "vehicle",
      label: "車両保険",
      raw: byPlan((id) =>
        plans[id].vehicle === "none"
          ? "付けない"
          : vehicleCoverOption(plans[id].vehicle).label,
      ),
      render: byPlan((id) =>
        plans[id].vehicle === "none" ? (
          <span className="text-muted-foreground">付けない</span>
        ) : (
          <span>
            {vehicleCoverOption(plans[id].vehicle).label}
            <span className="block text-xs text-muted-foreground">
              {vehicleCoverOption(plans[id].vehicle).note}
            </span>
          </span>
        ),
      ),
    },
    {
      key: "deductible",
      label: "免責金額（1回目／2回目）",
      raw: byPlan((id) =>
        plans[id].vehicle === "none"
          ? "—"
          : deductibleOption(plans[id].deductible).label,
      ),
      render: byPlan((id) =>
        plans[id].vehicle === "none"
          ? "—"
          : deductibleOption(plans[id].deductible).label,
      ),
    },
    {
      key: "riders",
      label: "特約",
      raw: byPlan((id) => results[id].activeRiderIds.join(",")),
      render: byPlan((id) => (
        <span>
          {results[id].activeRiderIds.length}件
          <span className="block text-xs text-muted-foreground">
            {riderNames(results[id].activeRiderIds)}
          </span>
        </span>
      )),
    },
    {
      key: "base",
      label: "基本保険料（4つの補償の合計）",
      raw: byPlan((id) => String(results[id].baseTotal)),
      render: byPlan((id) => money(results[id].baseTotal)),
    },
    {
      key: "riderTotal",
      label: "特約保険料",
      raw: byPlan((id) => String(results[id].riderTotal)),
      render: byPlan((id) => money(results[id].riderTotal)),
    },
    {
      key: "discount",
      label: "割引の合計",
      raw: byPlan((id) => String(results[id].discountTotal)),
      render: byPlan((id) => (
        <span className="text-muted-foreground">
          −{formatNumber(results[id].discountTotal)}円
        </span>
      )),
    },
    {
      key: "annual",
      label: "年間保険料",
      emphasis: true,
      raw: byPlan((id) => String(results[id].annual)),
      render: byPlan((id) => (
        <span className="text-base font-semibold">
          {money(results[id].annual)}
        </span>
      )),
    },
    {
      key: "monthly",
      label: "月払い（1回の額・12回）",
      raw: byPlan((id) => String(results[id].monthly)),
      render: byPlan((id) => (
        <span>
          {money(results[id].monthly)}
          <span className="block text-xs text-muted-foreground">
            年払いより{formatNumber(results[id].monthlyExtra)}円多い
          </span>
        </span>
      )),
    },
    {
      key: "delta",
      label: "標準案との差（年間）",
      raw: byPlan((id) =>
        String(results[id].annual - results.standard.annual),
      ),
      render: byPlan((id) => {
        const diff = results[id].annual - results.standard.annual;
        if (id === "standard") {
          return <span className="text-muted-foreground">比べるもとの案</span>;
        }
        if (diff === 0) {
          return <span className="text-muted-foreground">標準案と同じ額</span>;
        }
        return (
          <Delta
            value={diff}
            format={(v) => `${formatNumber(Math.abs(v))}円`}
            tones={{
              positive: "warning",
              negative: "success",
              zero: "muted",
            }}
            labels={{ positive: "高い", negative: "安い", zero: "同じ" }}
            showLabel
          />
        );
      }),
    },
  ];

  return rows;
}

function rowDiffers(row: CompareRow): boolean {
  return !(row.raw.rich === row.raw.standard && row.raw.standard === row.raw.value);
}

