/* ------------------------------------------------------------------ *
 * 内訳の行
 * ------------------------------------------------------------------ */

function buildBreakdownLines(result: PremiumResult): AmountLine[] {
  const lines: AmountLine[] = [];

  lines.push({ type: "heading", label: "基本保険料" });
  for (const line of result.coverageLines) {
    lines.push({
      label: `${line.label}（${line.cover}）`,
      amount: line.amount,
      note: line.detail,
    });
  }
  lines.push({
    type: "subtotal",
    label: "基本保険料 計",
    amount: result.baseTotal,
  });

  lines.push({ type: "heading", label: "特約" });
  if (result.riderLines.length === 0) {
    lines.push({ label: "付けている特約はありません", amount: 0 });
  } else {
    for (const line of result.riderLines) {
      lines.push({
        label: line.label,
        amount: line.amount,
        note: line.cover,
      });
    }
  }
  lines.push({
    type: "subtotal",
    label: "特約 計",
    amount: result.riderTotal,
  });
  lines.push({
    type: "subtotal",
    label: "小計（基本保険料 ＋ 特約）",
    amount: result.subtotal,
  });

  lines.push({ type: "heading", label: "割引・割増" });
  for (const adj of result.adjustments) {
    lines.push({
      label: adj.label,
      amount: adj.amount,
      kind: adj.kind,
      note: adj.detail,
    });
  }

  return lines;
}

/**
 * 保険料の算出。
 *
 * 画面の目的が「担当者がその場でお客さまに数字の根拠を説明できること」なので、
 * 合計だけでなく、掛けた係数と、その係数がどこから来たのかを文字列で持ち帰る。
 * ここに出てくる料率・割引率はすべて、この画面のためだけに作った架空の設定。
 */

import { formatNumber } from "@gunjo/ui";
import {
  BODILY_BASE,
  BODILY_LABEL,
  DEDUCTIBLE_OPTIONS,
  INJURY_OPTIONS,
  MILEAGE_OPTIONS,
  PROPERTY_OPTIONS,
  RIDERS,
  TODAY,
  USAGE_OPTIONS,
  VEHICLE_COVER_OPTIONS,
  findModel,
  type Deductible,
  type InjuryLimit,
  type PlanCoverage,
  type Policyholder,
  type PropertyLimit,
  type Vehicle,
  type VehicleCover,
} from "./data";

/* ------------------------------------------------------------------ *
 * 係数表
 * ------------------------------------------------------------------ */

/** 料率クラス 1〜9 の係数（クラス5を1.00とする） */
export const CLASS_FACTOR = [
  0, 0.55, 0.66, 0.79, 0.94, 1.0, 1.19, 1.42, 1.7, 2.03,
];

/** ノンフリート等級別の増減率（マイナスが割引）。事故なし */
const GRADE_NO_ACCIDENT: number[] = [
  0, 1.08, 0.63, 0.38, 0.07, -0.02, -0.13, -0.27, -0.38, -0.44, -0.46, -0.48,
  -0.5, -0.51, -0.52, -0.53, -0.54, -0.55, -0.56, -0.57, -0.63,
];

/** 前年に事故があったときの増減率（7等級以上は割引が小さくなる） */
const GRADE_WITH_ACCIDENT: number[] = [
  0, 1.08, 0.63, 0.38, 0.07, -0.02, -0.13, -0.14, -0.15, -0.18, -0.19, -0.2,
  -0.22, -0.24, -0.25, -0.28, -0.32, -0.44, -0.46, -0.5, -0.51,
];

export function gradeFactor(grade: number, prevAccident: boolean): number {
  const table = prevAccident ? GRADE_WITH_ACCIDENT : GRADE_NO_ACCIDENT;
  const clamped = Math.min(20, Math.max(1, Math.round(grade)));
  return table[clamped];
}

export const GOLD_DISCOUNT_RATE = 0.09;
export const ASV_DISCOUNT_RATE = 0.09;
export const ANTI_THEFT_DISCOUNT_RATE = 0.03;
/** インターネット申込割引。定額1万円だが小計の10%が上限 */
export const ONLINE_DISCOUNT_CAP = 10_000;
export const ONLINE_DISCOUNT_RATE = 0.1;
/** 月払いの分割割増 */
export const INSTALLMENT_SURCHARGE = 0.05;

/* ------------------------------------------------------------------ *
 * 年齢・車齢
 * ------------------------------------------------------------------ */

function toDate(iso: string): Date {
  const [y, m, d] = iso.split("-").map((n) => Number(n));
  return new Date(Date.UTC(y, (m ?? 1) - 1, d ?? 1));
}

/** TODAY 時点の満年齢 */
export function ageOn(birthDate: string, today: string = TODAY): number {
  const b = toDate(birthDate);
  const t = toDate(today);
  let age = t.getUTCFullYear() - b.getUTCFullYear();
  const beforeBirthday =
    t.getUTCMonth() < b.getUTCMonth() ||
    (t.getUTCMonth() === b.getUTCMonth() && t.getUTCDate() < b.getUTCDate());
  if (beforeBirthday) age -= 1;
  return age;
}

export interface AgeBand {
  factor: number;
  label: string;
}

/** 生年月日から運転者年齢条件を決める */
export function ageBand(birthDate: string, today: string = TODAY): AgeBand {
  const age = ageOn(birthDate, today);
  if (age < 21) return { factor: 1.62, label: "全年齢補償" };
  if (age < 26) return { factor: 1.28, label: "21歳以上補償" };
  if (age < 35) return { factor: 1.04, label: "26歳以上補償" };
  return { factor: 1.0, label: "35歳以上補償" };
}

/** 初度登録からの経過月数 */
export function monthsSinceFirstReg(
  vehicle: Vehicle,
  today: string = TODAY,
): number {
  const t = toDate(today);
  return (
    (t.getUTCFullYear() - vehicle.firstRegYear) * 12 +
    (t.getUTCMonth() + 1 - vehicle.firstRegMonth)
  );
}

export function formatVehicleAge(months: number): string {
  const y = Math.floor(months / 12);
  const m = months % 12;
  if (y === 0) return `${m}か月`;
  if (m === 0) return `${y}年`;
  return `${y}年${m}か月`;
}

/* ------------------------------------------------------------------ *
 * 選択肢の引き当て
 * ------------------------------------------------------------------ */

export function propertyOption(v: PropertyLimit) {
  return PROPERTY_OPTIONS.find((o) => o.value === v) ?? PROPERTY_OPTIONS[0];
}
export function injuryOption(v: InjuryLimit) {
  return INJURY_OPTIONS.find((o) => o.value === v) ?? INJURY_OPTIONS[0];
}
export function vehicleCoverOption(v: VehicleCover) {
  return (
    VEHICLE_COVER_OPTIONS.find((o) => o.value === v) ?? VEHICLE_COVER_OPTIONS[0]
  );
}
export function deductibleOption(v: Deductible) {
  return DEDUCTIBLE_OPTIONS.find((o) => o.value === v) ?? DEDUCTIBLE_OPTIONS[0];
}
export function usageOption(v: Vehicle["usage"]) {
  return USAGE_OPTIONS.find((o) => o.value === v) ?? USAGE_OPTIONS[0];
}
export function mileageOption(v: Vehicle["mileage"]) {
  return MILEAGE_OPTIONS.find((o) => o.value === v) ?? MILEAGE_OPTIONS[0];
}

/** その車・その補償で選べる特約に絞る */
export function eligibleRiderIds(
  vehicle: Vehicle,
  coverage: PlanCoverage,
  today: string = TODAY,
): string[] {
  const months = monthsSinceFirstReg(vehicle, today);
  return RIDERS.filter((r) => {
    if (r.requires === "newCar") return months <= 25;
    if (r.requires === "vehicleCover") return coverage.vehicle !== "none";
    return true;
  }).map((r) => r.id);
}

export function riderUnavailableReason(
  riderId: string,
  vehicle: Vehicle,
  coverage: PlanCoverage,
  today: string = TODAY,
): string | null {
  const rider = RIDERS.find((r) => r.id === riderId);
  if (!rider) return null;
  if (rider.requires === "newCar") {
    const months = monthsSinceFirstReg(vehicle, today);
    if (months > 25) {
      return `初度登録から${formatVehicleAge(months)}が経っているため、この特約は付けられません（25か月以内が条件）。`;
    }
  }
  if (rider.requires === "vehicleCover" && coverage.vehicle === "none") {
    return "車両保険を付けていないため、この特約は付けられません。";
  }
  return null;
}

/* ------------------------------------------------------------------ *
 * 算出結果
 * ------------------------------------------------------------------ */

export interface PremiumLine {
  key: string;
  label: string;
  /** 補償内容（無制限・5,000万円 など） */
  cover: string;
  /** 計算の根拠を一行で */
  detail: string;
  amount: number;
}

export interface AdjustmentLine {
  key: string;
  label: string;
  detail: string;
  amount: number;
  /** 割引は subtract、割増は add */
  kind: "add" | "subtract";
}

export interface PremiumResult {
  coverageLines: PremiumLine[];
  baseTotal: number;
  riderLines: PremiumLine[];
  riderTotal: number;
  subtotal: number;
  adjustments: AdjustmentLine[];
  discountTotal: number;
  surchargeTotal: number;
  annual: number;
  /** 月払いの1回の額 */
  monthly: number;
  monthlyTotal: number;
  /** 月払いで払ったときに年払いより多く払う額 */
  monthlyExtra: number;
  factors: {
    ageBand: AgeBand;
    age: number;
    usageLabel: string;
    usageFactor: number;
    mileageLabel: string;
    mileageFactor: number;
    gradeRate: number;
    vehicleAgeMonths: number;
  };
  /** 実際に効いている特約（条件を満たさないものは落としてある） */
  activeRiderIds: string[];
}

const yen = (n: number) => `${formatNumber(n)}円`;
const f2 = (n: number) => n.toFixed(2);

export function calculatePremium(
  policyholder: Policyholder,
  vehicle: Vehicle,
  coverage: PlanCoverage,
  today: string = TODAY,
): PremiumResult {
  const model = findModel(vehicle.modelCode);
  const band = ageBand(policyholder.birthDate, today);
  const usage = usageOption(vehicle.usage);
  const mileage = mileageOption(vehicle.mileage);
  const vehicleAgeMonths = monthsSinceFirstReg(vehicle, today);

  /** 補償にかかる共通の掛け目 */
  const common = band.factor * usage.factor * mileage.factor;
  const commonNote = `年齢条件${f2(band.factor)} × 用途${f2(usage.factor)} × 走行距離${f2(mileage.factor)}`;

  const bodilyClassFactor = CLASS_FACTOR[model.bodilyClass];
  const propertyClassFactor = CLASS_FACTOR[model.propertyClass];
  const injuryClassFactor = CLASS_FACTOR[model.injuryClass];
  const vehicleClassFactor = CLASS_FACTOR[model.vehicleClass];

  const property = propertyOption(coverage.property);
  const injury = injuryOption(coverage.injury);
  const cover = vehicleCoverOption(coverage.vehicle);
  const deductible = deductibleOption(coverage.deductible);

  const bodilyAmount = Math.round(BODILY_BASE * bodilyClassFactor * common);
  const propertyAmount = Math.round(
    property.base * propertyClassFactor * common,
  );
  const injuryAmount = Math.round(injury.base * injuryClassFactor * common);
  const vehicleAmount =
    coverage.vehicle === "none"
      ? 0
      : Math.round(
          model.vehicleValue *
            vehicleClassFactor *
            cover.rate *
            (1 - deductible.discount) *
            common,
        );

  const coverageLines: PremiumLine[] = [
    {
      key: "bodily",
      label: "対人賠償",
      cover: BODILY_LABEL,
      detail: `${yen(BODILY_BASE)} × 料率クラス${model.bodilyClass}(${f2(bodilyClassFactor)}) × ${commonNote}`,
      amount: bodilyAmount,
    },
    {
      key: "property",
      label: "対物賠償",
      cover: property.label,
      detail: `${yen(property.base)} × 料率クラス${model.propertyClass}(${f2(propertyClassFactor)}) × ${commonNote}`,
      amount: propertyAmount,
    },
    {
      key: "injury",
      label: "人身傷害",
      cover: injury.label,
      detail: `${yen(injury.base)} × 料率クラス${model.injuryClass}(${f2(injuryClassFactor)}) × ${commonNote}`,
      amount: injuryAmount,
    },
    {
      key: "vehicle",
      label: "車両保険",
      cover:
        coverage.vehicle === "none"
          ? "付けない"
          : `${cover.label}／${deductible.label}`,
      detail:
        coverage.vehicle === "none"
          ? "車両保険を付けていないため0円"
          : `車両保険金額${yen(model.vehicleValue)} × 料率クラス${model.vehicleClass}(${f2(vehicleClassFactor)}) × 型別料率${f2(cover.rate * 100)}% × 免責控除${f2(1 - deductible.discount)} × ${commonNote}`,
      amount: vehicleAmount,
    },
  ];

  const baseTotal = coverageLines.reduce((sum, l) => sum + l.amount, 0);

  const allowed = new Set(eligibleRiderIds(vehicle, coverage, today));
  const activeRiderIds = coverage.riders.filter((id) => allowed.has(id));
  const riderLines: PremiumLine[] = activeRiderIds.map((id) => {
    const rider = RIDERS.find((r) => r.id === id);
    return {
      key: id,
      label: rider ? rider.name : id,
      cover: rider ? rider.description : "",
      detail: "特約保険料（年額・定額）",
      amount: rider ? rider.price : 0,
    };
  });
  const riderTotal = riderLines.reduce((sum, l) => sum + l.amount, 0);

  const subtotal = baseTotal + riderTotal;

  const adjustments: AdjustmentLine[] = [];
  const rate = gradeFactor(policyholder.grade, policyholder.prevAccident);
  const gradeAmount = Math.round(subtotal * Math.abs(rate));
  const accidentNote = policyholder.prevAccident
    ? "前年に事故あり（事故有係数）"
    : "前年に事故なし";
  if (rate < 0) {
    adjustments.push({
      key: "grade",
      label: `${policyholder.grade}等級 割引`,
      detail: `小計${yen(subtotal)} × ${Math.round(Math.abs(rate) * 100)}%（${accidentNote}）`,
      amount: gradeAmount,
      kind: "subtract",
    });
  } else if (rate > 0) {
    adjustments.push({
      key: "grade",
      label: `${policyholder.grade}等級 割増`,
      detail: `小計${yen(subtotal)} × ${Math.round(rate * 100)}%（${accidentNote}）`,
      amount: gradeAmount,
      kind: "add",
    });
  }

  if (policyholder.license === "gold") {
    adjustments.push({
      key: "gold",
      label: "ゴールド免許割引",
      detail: `小計${yen(subtotal)} × ${Math.round(GOLD_DISCOUNT_RATE * 100)}%`,
      amount: Math.round(subtotal * GOLD_DISCOUNT_RATE),
      kind: "subtract",
    });
  }

  const asvEligible = vehicle.hasAsv && vehicleAgeMonths <= 36;
  if (asvEligible) {
    adjustments.push({
      key: "asv",
      label: "衝突被害軽減ブレーキ割引",
      detail: `小計${yen(subtotal)} × ${Math.round(ASV_DISCOUNT_RATE * 100)}%（初度登録から${formatVehicleAge(vehicleAgeMonths)}・36か月以内）`,
      amount: Math.round(subtotal * ASV_DISCOUNT_RATE),
      kind: "subtract",
    });
  }

  if (vehicle.hasAntiTheft && vehicleAmount > 0) {
    adjustments.push({
      key: "theft",
      label: "盗難防止装置割引",
      detail: `車両保険料${yen(vehicleAmount)} × ${Math.round(ANTI_THEFT_DISCOUNT_RATE * 100)}%`,
      amount: Math.round(vehicleAmount * ANTI_THEFT_DISCOUNT_RATE),
      kind: "subtract",
    });
  }

  const onlineAmount = Math.min(
    ONLINE_DISCOUNT_CAP,
    Math.round(subtotal * ONLINE_DISCOUNT_RATE),
  );
  adjustments.push({
    key: "online",
    label: "インターネット申込割引",
    detail:
      onlineAmount < ONLINE_DISCOUNT_CAP
        ? `小計${yen(subtotal)} × ${Math.round(ONLINE_DISCOUNT_RATE * 100)}%（定額${yen(ONLINE_DISCOUNT_CAP)}の上限にかからない）`
        : `定額${yen(ONLINE_DISCOUNT_CAP)}`,
    amount: onlineAmount,
    kind: "subtract",
  });

  const discountTotal = adjustments
    .filter((a) => a.kind === "subtract")
    .reduce((sum, a) => sum + a.amount, 0);
  const surchargeTotal = adjustments
    .filter((a) => a.kind === "add")
    .reduce((sum, a) => sum + a.amount, 0);

  const annual = Math.max(0, subtotal + surchargeTotal - discountTotal);
  const monthly = Math.ceil((annual * (1 + INSTALLMENT_SURCHARGE)) / 12);
  const monthlyTotal = monthly * 12;

  return {
    coverageLines,
    baseTotal,
    riderLines,
    riderTotal,
    subtotal,
    adjustments,
    discountTotal,
    surchargeTotal,
    annual,
    monthly,
    monthlyTotal,
    monthlyExtra: monthlyTotal - annual,
    factors: {
      ageBand: band,
      age: ageOn(policyholder.birthDate, today),
      usageLabel: usage.label,
      usageFactor: usage.factor,
      mileageLabel: mileage.label,
      mileageFactor: mileage.factor,
      gradeRate: rate,
      vehicleAgeMonths,
    },
    activeRiderIds,
  };
}

