/** 条件に合わなくなった特約を、各案から落とす */
function sanitizePlans(
  vehicle: Vehicle,
  plans: Record<PlanId, PlanCoverage>,
): Record<PlanId, PlanCoverage> {
  const fix = (coverage: PlanCoverage): PlanCoverage => {
    const allowed = new Set(eligibleRiderIds(vehicle, coverage));
    return { ...coverage, riders: coverage.riders.filter((id) => allowed.has(id)) };
  };
  return {
    rich: fix(plans.rich),
    standard: fix(plans.standard),
    value: fix(plans.value),
  };
}

