export function QuotationScreen() {
  /* ---- 見積一覧 ---- */
  const [quotes, setQuotes] = React.useState<QuoteRow[]>(INITIAL_QUOTES);
  const [activeQuoteId, setActiveQuoteId] = React.useState<string>(
    INITIAL_QUOTES[0].id,
  );
  const [loading, setLoading] = React.useState(false);
  const [statusFilter, setStatusFilter] = React.useState<StatusFilter>("all");
  const [query, setQuery] = React.useState("");
  const timer = React.useRef<number | null>(null);

  React.useEffect(() => {
    return () => {
      if (timer.current !== null) window.clearTimeout(timer.current);
    };
  }, []);

  const reload = () => {
    if (timer.current !== null) window.clearTimeout(timer.current);
    setLoading(true);
    timer.current = window.setTimeout(() => setLoading(false), 900);
  };

  /* ---- 見積の中身 ---- */
  const first = INITIAL_QUOTES[0];
  const [policyholder, setPolicyholder] = React.useState<Policyholder>(
    first.policyholder,
  );
  const [vehicle, setVehicle] = React.useState<Vehicle>(first.vehicle);
  const [plans, setPlans] = React.useState<Record<PlanId, PlanCoverage>>(() =>
    sanitizePlans(first.vehicle, defaultPlans()),
  );
  const [editingPlan, setEditingPlan] = React.useState<PlanId>("standard");
  const [selectedPlan, setSelectedPlan] = React.useState<PlanId>("standard");
  const [recommended, setRecommended] = React.useState<PlanId | "none">(
    "standard",
  );
  const [reasonDraft, setReasonDraft] = React.useState("");
  const [reasonEdited, setReasonEdited] = React.useState(false);
  const [confirmed, setConfirmed] = React.useState<ConfirmedQuote | null>(null);

  const results = React.useMemo<Record<PlanId, PremiumResult>>(
    () => ({
      rich: calculatePremium(policyholder, vehicle, plans.rich),
      standard: calculatePremium(policyholder, vehicle, plans.standard),
      value: calculatePremium(policyholder, vehicle, plans.value),
    }),
    [policyholder, vehicle, plans],
  );

  const generatedReason = React.useMemo(
    () =>
      recommended === "none"
        ? ""
        : buildRecommendationReason(
            recommended,
            policyholder,
            vehicle,
            plans,
            results,
          ),
    [recommended, policyholder, vehicle, plans, results],
  );

  const reason = reasonEdited ? reasonDraft : generatedReason;

  /* ---- 変更ハンドラ ---- */
  const touch = () => setConfirmed(null);

  const updatePolicyholder = (patch: Partial<Policyholder>) => {
    touch();
    setPolicyholder((prev) => ({ ...prev, ...patch }));
  };

  const updateVehicle = (patch: Partial<Vehicle>) => {
    touch();
    const next = { ...vehicle, ...patch };
    setVehicle(next);
    setPlans((current) => sanitizePlans(next, current));
  };

  const updatePlan = (planId: PlanId, patch: Partial<PlanCoverage>) => {
    touch();
    setPlans((prev) => {
      const next = { ...prev, [planId]: { ...prev[planId], ...patch } };
      return sanitizePlans(vehicle, next);
    });
  };

  const selectQuote = (row: QuoteRow) => {
    setActiveQuoteId(row.id);
    setPolicyholder(row.policyholder);
    setVehicle(row.vehicle);
    setPlans(sanitizePlans(row.vehicle, defaultPlans()));
    setEditingPlan("standard");
    setSelectedPlan("standard");
    setRecommended("standard");
    setReasonDraft("");
    setReasonEdited(false);
    setConfirmed(null);
  };

  const confirmQuote = () => {
    const target = quotes.find((q) => q.id === activeQuoteId);
    if (!target) return;
    const expiresAt = addDays(TODAY, 30);
    const result = results[selectedPlan];
    setConfirmed({
      no: target.no,
      planId: selectedPlan,
      annual: result.annual,
      monthly: result.monthly,
      issuedAt: TODAY,
      expiresAt,
    });
    setQuotes((prev) =>
      prev.map((q) =>
        q.id === activeQuoteId
          ? {
              ...q,
              status: "presented" as QuoteStatus,
              presentedPremium: result.annual,
              expiresAt,
            }
          : q,
      ),
    );
  };

  /* ---- 一覧の絞り込み ---- */
  const counts = React.useMemo(() => {
    return {
      all: quotes.length,
      draft: quotes.filter((q) => q.status === "draft").length,
      presented: quotes.filter((q) => q.status === "presented").length,
      expiring: quotes.filter((q) => q.status === "expiring").length,
    };
  }, [quotes]);

  const filteredQuotes = React.useMemo(() => {
    const q = query.trim();
    return quotes.filter((row) => {
      if (statusFilter !== "all" && row.status !== statusFilter) return false;
      if (q.length === 0) return true;
      return (
        row.no.includes(q) ||
        row.policyholder.name.includes(q) ||
        row.vehicle.modelCode.includes(q) ||
        row.owner.includes(q)
      );
    });
  }, [quotes, statusFilter, query]);

  const activeQuote = quotes.find((q) => q.id === activeQuoteId) ?? quotes[0];

  /* ---- 確定できるか ---- */
  const canConfirm =
    policyholder.name.trim().length > 0 &&
    (recommended === "none" || reason.trim().length > 0);
  const cannotConfirmReason =
    policyholder.name.trim().length === 0
      ? "契約者の氏名が空欄です。氏名を入れてから確定してください。"
      : "お勧めの理由が空欄です。理由を書くか、お勧めを「勧める案なし」にしてください。";

  /* ---- 一覧の列 ---- */
  const columns = React.useMemo<ColumnDef<QuoteRow, unknown>[]>(
    () => [
      {
        id: "no",
        header: "見積番号",
        accessorFn: (row: QuoteRow) => row.no,
        cell: ({ row }) => (
          <span className="font-mono text-xs whitespace-nowrap">
            {row.original.no}
          </span>
        ),
      },
      {
        id: "holder",
        header: "契約者",
        accessorFn: (row: QuoteRow) => row.policyholder.name,
        cell: ({ row }) => (
          <span className="whitespace-nowrap">
            <span className="font-medium">{row.original.policyholder.name}</span>
            <span className="block text-xs text-muted-foreground">
              {ageOn(row.original.policyholder.birthDate)}歳・
              {row.original.policyholder.grade}等級
            </span>
          </span>
        ),
      },
      {
        id: "vehicle",
        header: "車両（型式）",
        accessorFn: (row: QuoteRow) => row.vehicle.modelCode,
        cell: ({ row }) => (
          <span className="whitespace-nowrap">
            <span className="font-mono text-xs">
              {row.original.vehicle.modelCode}
            </span>
            <span className="block text-xs text-muted-foreground">
              {findModel(row.original.vehicle.modelCode).body}
            </span>
          </span>
        ),
      },
      {
        id: "owner",
        header: "担当者",
        accessorFn: (row: QuoteRow) => row.owner,
        cell: ({ row }) => (
          <span className="whitespace-nowrap">{row.original.owner}</span>
        ),
      },
      {
        id: "createdAt",
        header: "作成日",
        accessorFn: (row: QuoteRow) => row.createdAt,
        cell: ({ row }) => (
          <span className="whitespace-nowrap text-xs">
            {formatShortDate(row.original.createdAt)}
          </span>
        ),
      },
      {
        id: "status",
        header: "状態",
        accessorFn: (row: QuoteRow) => row.status,
        cell: ({ row }) => {
          const s = row.original.status;
          return (
            <Badge
              variant={STATUS_BADGE[s].variant}
              size="sm"
              icon={STATUS_BADGE[s].icon}
            >
              {STATUS_LABEL[s]}
            </Badge>
          );
        },
      },
      {
        id: "premium",
        header: "年間保険料",
        accessorFn: (row: QuoteRow) => row.presentedPremium ?? 0,
        cell: ({ row }) => (
          <span className="block whitespace-nowrap text-right tabular-nums">
            {row.original.presentedPremium === null
              ? "—"
              : formatCurrency(row.original.presentedPremium)}
          </span>
        ),
      },
      {
        id: "expiresAt",
        header: "有効期限",
        accessorFn: (row: QuoteRow) => row.expiresAt ?? "",
        cell: ({ row }) =>
          row.original.expiresAt === null ? (
            <span className="text-muted-foreground">—</span>
          ) : (
            <ExpiryBadge
              value={row.original.expiresAt}
              today={TODAY}
              warnWithinDays={10}
            />
          ),
      },
    ],
    [],
  );

  /* ---- 補償の明細（編集中の案） ---- */
  const editing = plans[editingPlan];
  const editingResult = results[editingPlan];
  const model = findModel(vehicle.modelCode);
  const vehicleAgeMonths = monthsSinceFirstReg(vehicle);
  const band = ageBand(policyholder.birthDate);

  const coverageColumns = React.useMemo<EditableColumn<CoverageRow>[]>(
    () => [
      {
        id: "name",
        header: "補償",
        headerLabel: "補償",
        width: "13rem",
        cell: (row) => (
          <span className="block">
            <span className="font-medium">{COVERAGE_LABEL[row.key]}</span>
            <span className="block text-xs text-muted-foreground">
              {COVERAGE_NOTE[row.key]}
            </span>
          </span>
        ),
      },
      {
        id: "cover",
        header: "補償内容",
        headerLabel: "補償内容",
        minWidth: "13rem",
        cell: (row, ctx) => {
          if (row.key === "bodily") {
            return (
              <span className="text-sm">
                無制限
                <span className="block text-xs text-muted-foreground">
                  3案とも無制限で組みます
                </span>
              </span>
            );
          }
          if (row.key === "property") {
            return (
              <Select
                aria-label={ctx.ariaLabel}
                value={editing.property}
                onChange={(e) =>
                  updatePlan(editingPlan, {
                    property: e.target.value as PropertyLimit,
                  })
                }
              >
                {PROPERTY_OPTIONS.map((o) => (
                  <option key={o.value} value={o.value}>
                    {o.label}
                  </option>
                ))}
              </Select>
            );
          }
          if (row.key === "injury") {
            return (
              <Select
                aria-label={ctx.ariaLabel}
                value={editing.injury}
                onChange={(e) =>
                  updatePlan(editingPlan, {
                    injury: e.target.value as InjuryLimit,
                  })
                }
              >
                {INJURY_OPTIONS.map((o) => (
                  <option key={o.value} value={o.value}>
                    {o.label}
                  </option>
                ))}
              </Select>
            );
          }
          return (
            <Select
              aria-label={ctx.ariaLabel}
              value={editing.vehicle}
              onChange={(e) =>
                updatePlan(editingPlan, {
                  vehicle: e.target.value as VehicleCover,
                })
              }
            >
              {VEHICLE_COVER_OPTIONS.map((o) => (
                <option key={o.value} value={o.value}>
                  {o.label}
                </option>
              ))}
            </Select>
          );
        },
      },
      {
        id: "deductible",
        header: "免責金額（1回目／2回目）",
        headerLabel: "免責金額",
        minWidth: "15rem",
        cell: (row, ctx) => {
          if (row.key !== "vehicle") {
            return <span className="text-sm text-muted-foreground">—</span>;
          }
          if (editing.vehicle === "none") {
            return (
              <span className="text-sm text-muted-foreground">
                車両保険なし
              </span>
            );
          }
          return (
            <Select
              aria-label={ctx.ariaLabel}
              value={editing.deductible}
              onChange={(e) =>
                updatePlan(editingPlan, {
                  deductible: e.target.value as Deductible,
                })
              }
            >
              {DEDUCTIBLE_OPTIONS.map((o) => (
                <option key={o.value} value={o.value}>
                  {o.label}
                </option>
              ))}
            </Select>
          );
        },
      },
      {
        id: "premium",
        header: "年間保険料",
        headerLabel: "年間保険料",
        align: "right",
        width: "9rem",
        cell: (row) => {
          const line = editingResult.coverageLines.find(
            (l) => l.key === row.key,
          );
          return (
            <span className="block text-right tabular-nums">
              {formatCurrency(line ? line.amount : 0)}
            </span>
          );
        },
      },
      {
        id: "basis",
        header: "計算の根拠",
        headerLabel: "計算の根拠",
        minWidth: "22rem",
        cell: (row) => {
          const line = editingResult.coverageLines.find(
            (l) => l.key === row.key,
          );
          return (
            <span className="block text-xs leading-relaxed text-muted-foreground">
              {line ? line.detail : ""}
            </span>
          );
        },
      },
    ],
    // updatePlan は vehicle と editingPlan を閉じ込むので、両方を依存に入れる
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [editing, editingPlan, editingResult, vehicle],
  );

  const availableRiderIds = React.useMemo(
    () => new Set(eligibleRiderIds(vehicle, editing)),
    [vehicle, editing],
  );

  /* ---------------------------------------------------------------- */

  return (
    <main className="mx-auto w-full max-w-[100rem] px-4 py-6 sm:px-6 lg:px-8">
      <DesktopPageHeader
        eyebrow="架空ダミー損害保険 ／ 代理店業務システム"
        title="自動車保険 見積作成"
        subtitle="お客さまと画面を一緒に見ながら、条件を入れて3案を組み、勧める案と理由をお伝えします。"
        actions={
          <Cluster gap={2} align="center">
            <span className="text-xs text-muted-foreground">
              本日 {formatShortDate(TODAY)}
            </span>
            <Badge variant="outline" size="sm">
              担当 高梨 諒
            </Badge>
          </Cluster>
        }
      />

      <div className="mt-6 space-y-10">
        {/* ================= 見積一覧 ================= */}
        <section aria-labelledby="sec-list" className="space-y-4">
          <h2 id="sec-list" className="text-xl font-semibold tracking-tight">
            進行中の見積
          </h2>

          <StatGroup
            cols={{ base: 1, sm: 2, lg: 4 }}
            items={[
              {
                label: "進行中の見積",
                value: `${counts.all}件`,
                hint: "作成中・提示済み・期限間近の合計",
              },
              {
                label: "作成中",
                value: `${counts.draft}件`,
                hint: "まだ提示していない見積",
              },
              {
                label: "提示済み",
                value: `${counts.presented}件`,
                hint: "お客さまにお渡し済み",
              },
              {
                label: "有効期限切れ間近",
                value: `${counts.expiring}件`,
                hint: "残り10日以内。作り直しの連絡が要ります",
              },
            ]}
          />

          <Card>
            <CardHeader>
              <CardTitle as="h3">見積の一覧</CardTitle>
              <CardDescription>
                行を選ぶと、その見積の条件が下の作成欄に入ります。いまは
                {activeQuote.policyholder.name} さまの見積を開いています。
              </CardDescription>
              <div className="space-y-3 pt-2">
                <FilterChips
                  aria-label="状態で絞り込む"
                  value={statusFilter}
                  onValueChange={(v) => setStatusFilter(v as StatusFilter)}
                  items={[
                    { value: "all", label: "すべて", count: counts.all },
                    { value: "draft", label: "作成中", count: counts.draft },
                    {
                      value: "presented",
                      label: "提示済み",
                      count: counts.presented,
                    },
                    {
                      value: "expiring",
                      label: "期限間近",
                      count: counts.expiring,
                    },
                  ]}
                />
                <Cluster gap={2} align="center">
                  <div className="min-w-0 flex-1 basis-64">
                    <SearchInput
                      value={query}
                      onValueChange={setQuery}
                      placeholder="見積番号・契約者・型式・担当者で探す"
                      aria-label="見積を探す"
                    />
                  </div>
                  <Button
                    type="button"
                    variant="outline"
                    onClick={reload}
                    loading={loading}
                  >
                    <IconRefresh aria-hidden className="size-4" />
                    再読み込み
                  </Button>
                </Cluster>
              </div>
            </CardHeader>
            <CardContent>
              {loading ? (
                <div
                  aria-busy="true"
                  aria-live="polite"
                  className="space-y-3 rounded-md border border-border p-4"
                >
                  <Cluster gap={2} align="center">
                    <Spinner size="sm" />
                    <span className="text-sm text-muted-foreground">
                      見積一覧を読み込んでいます
                    </span>
                  </Cluster>
                  {[0, 1, 2, 3, 4, 5].map((i) => (
                    <div key={i} className="flex items-center gap-3">
                      <Skeleton className="h-4 w-32" />
                      <Skeleton className="h-4 w-24" />
                      <Skeleton className="h-4 w-20" />
                      <Skeleton className="hidden h-4 w-28 sm:block" />
                      <Skeleton className="hidden h-4 w-24 md:block" />
                    </div>
                  ))}
                </div>
              ) : filteredQuotes.length === 0 ? (
                <EmptyState
                  headingLevel={4}
                  icon={<IconAlertTriangle aria-hidden className="size-8" />}
                  title="この条件に合う見積はありません"
                  description="状態の絞り込みか、検索の言葉を変えてみてください。進行中の見積はぜんぶで8件あります。"
                  action={
                    <Button
                      type="button"
                      variant="outline"
                      onClick={() => {
                        setStatusFilter("all");
                        setQuery("");
                      }}
                    >
                      絞り込みを外す
                    </Button>
                  }
                />
              ) : (
                <DataTable<QuoteRow, unknown>
                  columns={columns}
                  data={filteredQuotes}
                  filter={null}
                  pageSize={10}
                  caption="進行中の見積の一覧"
                  captionClassName="sr-only"
                  hidePaginationSummary={false}
                  onRowClick={selectQuote}
                  getRowState={(row) =>
                    row.id === activeQuoteId ? "selected" : undefined
                  }
                  renderCard={(row) => (
                    <div className="space-y-2">
                      <div className="flex flex-wrap items-center gap-2">
                        <span className="font-mono text-xs">{row.no}</span>
                        <Badge
                          variant={STATUS_BADGE[row.status].variant}
                          size="sm"
                          icon={STATUS_BADGE[row.status].icon}
                        >
                          {STATUS_LABEL[row.status]}
                        </Badge>
                      </div>
                      <div className="text-sm font-medium">
                        {row.policyholder.name}
                        <span className="pl-2 text-xs font-normal text-muted-foreground">
                          {ageOn(row.policyholder.birthDate)}歳・
                          {row.policyholder.grade}等級
                        </span>
                      </div>
                      <dl className="grid grid-cols-2 gap-x-3 gap-y-1 text-xs text-muted-foreground">
                        <dt>車両（型式）</dt>
                        <dd className="text-foreground">
                          {row.vehicle.modelCode}
                        </dd>
                        <dt>担当者</dt>
                        <dd className="text-foreground">{row.owner}</dd>
                        <dt>作成日</dt>
                        <dd className="text-foreground">
                          {formatShortDate(row.createdAt)}
                        </dd>
                        <dt>年間保険料</dt>
                        <dd className="text-foreground tabular-nums">
                          {row.presentedPremium === null
                            ? "—"
                            : formatCurrency(row.presentedPremium)}
                        </dd>
                      </dl>
                      {row.expiresAt === null ? null : (
                        <ExpiryBadge
                          value={row.expiresAt}
                          today={TODAY}
                          warnWithinDays={10}
                        />
                      )}
                    </div>
                  )}
                />
              )}
            </CardContent>
          </Card>
        </section>

        {/* ================= 契約条件 ================= */}
        <section aria-labelledby="sec-conditions" className="space-y-4">
          <h2
            id="sec-conditions"
            className="text-xl font-semibold tracking-tight"
          >
            契約者と車両の条件
          </h2>
          <p className="text-sm text-muted-foreground">
            ここを変えると、3案の保険料はその場で計算し直されます。
          </p>

          <div className="grid gap-4 lg:grid-cols-2">
            <Card>
              <CardHeader>
                <CardTitle as="h3">契約者</CardTitle>
                <CardDescription>
                  記名被保険者の情報を聞き取って入れます。
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <Input
                  label="氏名"
                  value={policyholder.name}
                  onChange={(e) => updatePolicyholder({ name: e.target.value })}
                  placeholder="例：桐生 沙代"
                  autoComplete="off"
                />

                <DatePicker
                  label="生年月日"
                  description={`${ageOn(policyholder.birthDate)}歳。運転者年齢条件は「${band.label}」で計算しています（係数 ${band.factor.toFixed(2)}）。`}
                  value={isoToDate(policyholder.birthDate)}
                  onValueChange={(d) => {
                    if (d) updatePolicyholder({ birthDate: dateToIso(d) });
                  }}
                  editable
                  startMonth={new Date(1940, 0, 1)}
                  endMonth={new Date(2010, 11, 31)}
                />

                <div className="space-y-2">
                  <span
                    id="license-label"
                    className="block text-sm font-medium"
                  >
                    免許の色
                  </span>
                  <SegmentedControl
                    aria-label="免許の色"
                    value={policyholder.license}
                    onValueChange={(v) =>
                      updatePolicyholder({ license: v as LicenseColor })
                    }
                    options={LICENSE_OPTIONS.map((o) => ({
                      value: o.value,
                      label: o.label,
                    }))}
                  />
                  <p className="text-xs text-muted-foreground">
                    ゴールドのときだけ、小計の9%が割引になります。
                  </p>
                </div>

                <Select
                  label="ノンフリート等級"
                  description={`いまの増減率は ${
                    gradeFactor(policyholder.grade, policyholder.prevAccident) <
                    0
                      ? `割引${Math.round(
                          Math.abs(
                            gradeFactor(
                              policyholder.grade,
                              policyholder.prevAccident,
                            ),
                          ) * 100,
                        )}%`
                      : `割増${Math.round(
                          gradeFactor(
                            policyholder.grade,
                            policyholder.prevAccident,
                          ) * 100,
                        )}%`
                  } です。`}
                  value={String(policyholder.grade)}
                  onChange={(e) =>
                    updatePolicyholder({ grade: Number(e.target.value) })
                  }
                >
                  {Array.from({ length: 20 }, (_, i) => i + 1).map((g) => {
                    const rate = gradeFactor(g, policyholder.prevAccident);
                    const label =
                      rate < 0
                        ? `割引${Math.round(Math.abs(rate) * 100)}%`
                        : `割増${Math.round(rate * 100)}%`;
                    return (
                      <option key={g} value={String(g)}>
                        {g}等級（{label}）
                      </option>
                    );
                  })}
                </Select>

                <div className="space-y-2">
                  <span className="block text-sm font-medium">
                    前年の事故の有無
                  </span>
                  <SegmentedControl
                    aria-label="前年の事故の有無"
                    value={policyholder.prevAccident ? "yes" : "no"}
                    onValueChange={(v) =>
                      updatePolicyholder({ prevAccident: v === "yes" })
                    }
                    options={[
                      { value: "no", label: "事故なし" },
                      { value: "yes", label: "事故あり" },
                    ]}
                  />
                  <p className="text-xs text-muted-foreground">
                    事故ありのときは事故有係数を使うので、同じ等級でも割引が小さくなります。
                  </p>
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle as="h3">車両</CardTitle>
                <CardDescription>
                  型式から料率クラスと車両保険金額を引きます。
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <Select
                  label="型式"
                  description={`${model.body}／車両保険金額 ${formatCurrency(model.vehicleValue)}／料率クラス 対人${model.bodilyClass}・対物${model.propertyClass}・傷害${model.injuryClass}・車両${model.vehicleClass}`}
                  value={vehicle.modelCode}
                  onChange={(e) =>
                    updateVehicle({ modelCode: e.target.value })
                  }
                >
                  {VEHICLE_MODELS.map((m) => (
                    <option key={m.code} value={m.code}>
                      {m.code}（{m.body}）
                    </option>
                  ))}
                </Select>

                <div className="grid grid-cols-2 gap-3">
                  <Select
                    label="初度登録の年"
                    value={String(vehicle.firstRegYear)}
                    onChange={(e) =>
                      updateVehicle({ firstRegYear: Number(e.target.value) })
                    }
                  >
                    {Array.from({ length: 22 }, (_, i) => 2005 + i).map((y) => (
                      <option key={y} value={String(y)}>
                        {y}年
                      </option>
                    ))}
                  </Select>
                  <Select
                    label="初度登録の月"
                    value={String(vehicle.firstRegMonth)}
                    onChange={(e) =>
                      updateVehicle({ firstRegMonth: Number(e.target.value) })
                    }
                  >
                    {Array.from({ length: 12 }, (_, i) => i + 1).map((m) => (
                      <option key={m} value={String(m)}>
                        {m}月
                      </option>
                    ))}
                  </Select>
                </div>
                <p className="text-xs text-muted-foreground">
                  初度登録から{formatVehicleAge(vehicleAgeMonths)}
                  経っています。車両新価特約は25か月以内、衝突被害軽減ブレーキ割引は36か月以内が条件です。
                </p>

                <Select
                  label="用途"
                  description={`保険料の掛け目は ${(
                    USAGE_OPTIONS.find((o) => o.value === vehicle.usage)
                      ?.factor ?? 1
                  ).toFixed(2)} です。`}
                  value={vehicle.usage}
                  onChange={(e) =>
                    updateVehicle({ usage: e.target.value as Usage })
                  }
                >
                  {USAGE_OPTIONS.map((o) => (
                    <option key={o.value} value={o.value}>
                      {o.label}
                    </option>
                  ))}
                </Select>

                <Select
                  label="年間走行距離の区分"
                  description={`保険料の掛け目は ${(
                    MILEAGE_OPTIONS.find((o) => o.value === vehicle.mileage)
                      ?.factor ?? 1
                  ).toFixed(2)} です。`}
                  value={vehicle.mileage}
                  onChange={(e) =>
                    updateVehicle({ mileage: e.target.value as MileageBand })
                  }
                >
                  {MILEAGE_OPTIONS.map((o) => (
                    <option key={o.value} value={o.value}>
                      {o.label}
                    </option>
                  ))}
                </Select>

                <div className="space-y-2">
                  <span className="block text-sm font-medium">安全装置</span>
                  <CheckList
                    aria-label="安全装置"
                    items={[
                      {
                        id: "asv",
                        label: "衝突被害軽減ブレーキ（ASV）",
                        description:
                          vehicle.hasAsv && vehicleAgeMonths <= 36
                            ? `初度登録から${formatVehicleAge(vehicleAgeMonths)}。小計の9%が割引になります。`
                            : vehicle.hasAsv
                              ? `初度登録から${formatVehicleAge(vehicleAgeMonths)}。36か月を超えているので割引の対象外です。`
                              : "装置なし。割引はつきません。",
                        checked: vehicle.hasAsv,
                        trailing:
                          vehicle.hasAsv && vehicleAgeMonths <= 36 ? (
                            <Badge variant="success" size="sm" icon={<IconCheck />}>
                              割引あり
                            </Badge>
                          ) : (
                            <Badge variant="outline" size="sm">
                              割引なし
                            </Badge>
                          ),
                      },
                      {
                        id: "theft",
                        label: "盗難防止装置",
                        description:
                          vehicle.hasAntiTheft && editing.vehicle !== "none"
                            ? "車両保険料の3%が割引になります。"
                            : vehicle.hasAntiTheft
                              ? "車両保険を付けていないため、この案では割引がつきません。"
                              : "装置なし。割引はつきません。",
                        checked: vehicle.hasAntiTheft,
                        trailing:
                          vehicle.hasAntiTheft && editing.vehicle !== "none" ? (
                            <Badge variant="success" size="sm" icon={<IconCheck />}>
                              割引あり
                            </Badge>
                          ) : (
                            <Badge variant="outline" size="sm">
                              割引なし
                            </Badge>
                          ),
                      },
                    ]}
                    onCheckedChange={(id, checked) =>
                      id === "asv"
                        ? updateVehicle({ hasAsv: checked })
                        : updateVehicle({ hasAntiTheft: checked })
                    }
                  />
                </div>
              </CardContent>
            </Card>
          </div>
        </section>

        {/* ================= 補償の組み立て ================= */}
        <section aria-labelledby="sec-coverage" className="space-y-4">
          <h2
            id="sec-coverage"
            className="text-xl font-semibold tracking-tight"
          >
            補償の組み立て
          </h2>
          <p className="text-sm text-muted-foreground">
            3つの案はそれぞれ別に組めます。いま編集している案を選んでから、補償と特約を変えてください。
          </p>

          <div className="sticky top-0 z-20 rounded-lg border border-border bg-background/95 p-3 shadow-sm backdrop-blur">
            <div className="flex flex-wrap items-end justify-between gap-3">
              <div className="min-w-0">
                <span className="block text-xs text-muted-foreground">
                  編集中の案
                </span>
                <span className="block text-sm font-semibold">
                  {PLAN_META.find((p) => p.id === editingPlan)?.name}／
                  {policyholder.name || "（氏名未入力）"} さま
                </span>
              </div>
              <div className="text-right" aria-live="polite">
                <span className="block text-xs text-muted-foreground">
                  この案の年間保険料
                </span>
                <span className="block text-lg font-semibold tabular-nums">
                  {formatCurrency(editingResult.annual)}
                </span>
                <span className="block text-xs text-muted-foreground">
                  月払いなら1回 {formatCurrency(editingResult.monthly)} ×12回
                </span>
              </div>
            </div>
          </div>

          <SegmentedControl
            aria-label="編集する案を選ぶ"
            value={editingPlan}
            onValueChange={(v) => setEditingPlan(v as PlanId)}
            options={PLAN_META.map((p) => ({ value: p.id, label: p.name }))}
          />

          <Card>
            <CardHeader>
              <CardTitle as="h3">
                4つの補償（{PLAN_META.find((p) => p.id === editingPlan)?.name}）
              </CardTitle>
              <CardDescription>
                右端に、その補償の保険料がどう出たかを載せています。料率は本画面かぎりの架空の設定です。
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <EditableDataTable<CoverageRow>
                columns={coverageColumns}
                rows={COVERAGE_ROWS}
                getRowId={(row) => row.key}
                rowLabel={(index) => COVERAGE_LABEL[COVERAGE_ROWS[index].key]}
                caption={`${PLAN_META.find((p) => p.id === editingPlan)?.name}の補償の明細`}
                renderFooterCell={(column) => {
                  if (column.id === "name") return "基本保険料 計";
                  if (column.id === "premium")
                    return (
                      <span className="block text-right tabular-nums">
                        {formatCurrency(editingResult.baseTotal)}
                      </span>
                    );
                  if (column.id === "basis")
                    return (
                      <span className="text-xs text-muted-foreground">
                        年齢条件{band.factor.toFixed(2)}・用途
                        {editingResult.factors.usageFactor.toFixed(2)}・走行距離
                        {editingResult.factors.mileageFactor.toFixed(2)}
                        を、4つの補償すべてに掛けています
                      </span>
                    );
                  return null;
                }}
              />

              <div className="grid gap-3 sm:grid-cols-3">
                <Statistic
                  label="基本保険料"
                  value={formatCurrency(editingResult.baseTotal)}
                  hint="4つの補償の合計"
                />
                <Statistic
                  label="特約保険料"
                  value={formatCurrency(editingResult.riderTotal)}
                  hint={`${editingResult.activeRiderIds.length}件の合計`}
                />
                <Statistic
                  label="年間保険料"
                  value={formatCurrency(editingResult.annual)}
                  hint={`割引の合計 ${formatNumber(editingResult.discountTotal)}円を引いた額`}
                />
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle as="h3">
                特約（{PLAN_META.find((p) => p.id === editingPlan)?.name}）
              </CardTitle>
              <CardDescription>
                {RIDERS.length}件から選びます。選んだ分は特約保険料として、そのまま年間保険料に足されます。
              </CardDescription>
            </CardHeader>
            <CardContent>
              <CheckboxCardGroup
                aria-label="特約を選ぶ"
                value={editing.riders}
                onValueChange={(values) =>
                  updatePlan(editingPlan, { riders: values })
                }
                className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3"
              >
                {RIDERS.map((rider) => {
                  const unavailable = riderUnavailableReason(
                    rider.id,
                    vehicle,
                    editing,
                  );
                  return (
                    <CheckboxCard
                      key={rider.id}
                      value={rider.id}
                      title={rider.name}
                      description={rider.description}
                      price={`${formatNumber(rider.price)}円`}
                      disabled={!availableRiderIds.has(rider.id)}
                      disabledReason={unavailable ?? undefined}
                    />
                  );
                })}
              </CheckboxCardGroup>
            </CardContent>
          </Card>
        </section>

        {/* ================= 比較・お勧め・内訳・確定 ================= */}
        <PlanSections
          policyholder={policyholder}
          vehicle={vehicle}
          plans={plans}
          results={results}
          recommended={recommended}
          onRecommendedChange={(value) => {
            touch();
            setRecommended(value);
            setReasonDraft("");
            setReasonEdited(false);
          }}
          reason={reason}
          generatedReason={generatedReason}
          reasonEdited={reasonEdited}
          onReasonChange={(value) => {
            setReasonDraft(value);
            setReasonEdited(true);
          }}
          onRegenerateReason={() => {
            setReasonDraft("");
            setReasonEdited(false);
          }}
          selected={selectedPlan}
          onSelectedChange={(value) => {
            touch();
            setSelectedPlan(value);
          }}
          confirmed={confirmed}
          onConfirm={confirmQuote}
          canConfirm={canConfirm}
          cannotConfirmReason={cannotConfirmReason}
        />

        <p className="pb-8 text-xs text-muted-foreground">
          この画面に出てくる保険会社・代理店・担当者・契約者・型式・料率・割引率は、すべて架空のものです。
        </p>
      </div>
    </main>
  );
}

/**
 * 「担当者のお勧め」の理由の文案を、そのお客さまの条件から組み立てる。
 *
 * よく売れているから、ではなく、いま画面に入っている等級・用途・走行距離・
 * 免許の色・初度登録・3案の保険料差から文を作る。担当者はこの文案を
 * そのまま使ってもいいし、画面上で書き換えてもいい。
 */

import { formatNumber } from "@gunjo/ui";
import {
  PLAN_META,
  findModel,
  type PlanCoverage,
  type PlanId,
  type Policyholder,
  type Vehicle,
} from "./data";
import {
  formatVehicleAge,
  gradeFactor,
  injuryOption,
  mileageOption,
  monthsSinceFirstReg,
  type PremiumResult,
} from "./pricing";

const yen = (n: number) => `${formatNumber(n)}円`;

export function planName(planId: PlanId): string {
  return PLAN_META.find((p) => p.id === planId)?.name ?? "";
}

export function buildRecommendationReason(
  planId: PlanId,
  policyholder: Policyholder,
  vehicle: Vehicle,
  plans: Record<PlanId, PlanCoverage>,
  results: Record<PlanId, PremiumResult>,
): string {
  const coverage = plans[planId];
  const result = results[planId];
  const model = findModel(vehicle.modelCode);
  const sentences: string[] = [];

  // 1. 等級の見通し
  if (!policyholder.prevAccident && policyholder.grade < 20) {
    const next = policyholder.grade + 1;
    const nextRate = Math.round(Math.abs(gradeFactor(next, false)) * 100);
    const nowRate = Math.round(
      Math.abs(gradeFactor(policyholder.grade, false)) * 100,
    );
    sentences.push(
      `今年は無事故なので、来年は${next}等級（割引${nextRate}%）に上がります。いまの${policyholder.grade}等級で割引${nowRate}%ですから、ここで補償を厚くしても翌年の負担の増え方は小さく収まります。`,
    );
  } else if (policyholder.prevAccident) {
    const nowRate = Math.round(
      Math.abs(gradeFactor(policyholder.grade, true)) * 100,
    );
    sentences.push(
      `前年の事故があるため、${policyholder.grade}等級でも割引は${nowRate}%にとどまっています。事故有係数が抜けるまでは保険料が下がりにくいので、この期間の自己負担の出方から案を選びました。`,
    );
  }

  // 2. 使い方（用途と走行距離）
  const mileage = mileageOption(vehicle.mileage);
  const injury = injuryOption(coverage.injury);
  if (vehicle.usage === "commute") {
    sentences.push(
      `通勤・通学で毎日運転されるので、ご自身とご家族のけがに使える人身傷害を${injury.label}にしています。`,
    );
  } else if (vehicle.usage === "business") {
    sentences.push(
      `お仕事で運転される分、事故に遭う機会も多くなります。人身傷害を${injury.label}にしてあります。`,
    );
  } else if (mileage.factor < 1) {
    sentences.push(
      `年間走行距離が${mileage.label}なので、距離の区分で保険料が${Math.round((1 - mileage.factor) * 100)}%下がっています。走る量に対して過不足のない組み方です。`,
    );
  }

  // 3. 車両保険をどうしたか（3案の差額を根拠にする）
  const withVehicle = (["rich", "standard", "value"] as PlanId[]).find(
    (id) => plans[id].vehicle !== "none",
  );
  const withoutVehicle = (["value", "standard", "rich"] as PlanId[]).find(
    (id) => plans[id].vehicle === "none",
  );
  if (coverage.vehicle !== "none" && withoutVehicle) {
    const diff = result.annual - results[withoutVehicle].annual;
    if (diff > 0) {
      sentences.push(
        `車両保険を外せば年間${yen(diff)}下がりますが、車両保険金額${yen(model.vehicleValue)}のお車の修理費がそのまま自己負担になります。この案では車両保険を残しました。`,
      );
    }
  } else if (coverage.vehicle === "none" && withVehicle) {
    const diff = results[withVehicle].annual - result.annual;
    const months = monthsSinceFirstReg(vehicle);
    if (diff > 0) {
      sentences.push(
        `初度登録から${formatVehicleAge(months)}が経ち、車両保険金額は${yen(model.vehicleValue)}です。車両保険を外すことで年間${yen(diff)}を抑えています。修理費は自己負担になる点だけご確認ください。`,
      );
    }
  }

  // 4. いま効いている割引
  const discountNotes: string[] = [];
  const gold = result.adjustments.find((a) => a.key === "gold");
  if (gold) discountNotes.push(`ゴールド免許割引${yen(gold.amount)}`);
  const asv = result.adjustments.find((a) => a.key === "asv");
  if (asv) discountNotes.push(`衝突被害軽減ブレーキ割引${yen(asv.amount)}`);
  const theft = result.adjustments.find((a) => a.key === "theft");
  if (theft) discountNotes.push(`盗難防止装置割引${yen(theft.amount)}`);
  if (discountNotes.length > 0) {
    sentences.push(
      `いまのご契約条件では${discountNotes.join("と")}が効いています。`,
    );
  }

  // 5. 標準案との差
  if (planId !== "standard") {
    const diff = result.annual - results.standard.annual;
    if (diff !== 0) {
      sentences.push(
        diff > 0
          ? `標準案より年間${yen(diff)}高くなりますが、その分は上に書いた補償の差です。`
          : `標準案より年間${yen(Math.abs(diff))}安くなります。減らした補償は上のとおりです。`,
      );
    }
  }

  return sentences.join("");
}
